import { TabContext, TabList, TabPanel } from "@mui/lab";
import {
  Box,
  Container,
  createTheme,
  Fade,
  Grid,
  styled,
  Tab,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import { useState } from "react";
import managementIcon from "../../../../assets/images/managementIcon.svg";
import managementActiveIcon from "../../../../assets/images/managementActive.svg";
import reportsIcon from "../../../../assets/images/reports.svg";
import reportsActiveIcon from "../../../../assets/images/reportsActive.svg";
import delegationWorkflowIcon from "../../../../assets/images/delegationWorkflow.svg";
import delegationActiveIcon from "../../../../assets/images/delegationActive.svg";
import automationIcon from "../../../../assets/images/automation.svg";
import automationActiveIcon from "../../../../assets/images/automationActive.svg";
import backupIcon from "../../../../assets/images/backup.svg";
import backupActiveIcon from "../../../../assets/images/backupActive.svg";
import ADManagerCards from "./ADManagerCards";
import "../../../../styles/animation.css";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import FallbackSpinner from "src/@core/components/spinner";

const ADManager = ({ featuresTitle }) => {
  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "16px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },
    [theme.breakpoints.up("md")]: {
      fontSize: "20px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "24px",
    },
    fontWeight: 600,
    lineHeight: "28px",
    textTransform: "capitalize",
    // wordBreak: "break-word",
    textWrap: "wrap",
    whiteSpace: "normal",
  }));
  const CustomTabPanel = styled(TabPanel)(({ theme }) => ({
    [theme.breakpoints.down("sm")]: {
      padding: 0,
    },
    [theme.breakpoints.up("sm")]: {
      padding: "25px",
    },
  }));
  const [value, setValue] = useState("management");
  const handleChange = (event, newValue) => {
    setValue(newValue);
  };
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  // const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const [itSolutionFeatures, setItSolutionFeatures] = useState([]);
  const [subFeaturesData, setSubFeaturesData] = useState([]);
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();

  const fetchItSolutionFeatures = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_FEATURES.list(itSolutionId))
      .then((response) => {
        setItSolutionFeatures(response.data.data);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setValue(responseData[0].title);
        }
        responseData.map((item) => {
          fetchITSolutionSubFeatures(item.id, item.title);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchITSolutionSubFeatures = (id, title) => {
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_SUB_FEATURES.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setSubFeaturesData((prevData) => ({
          ...prevData,
          [title]: responseData,
        }));
      })

      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchItSolutionFeatures();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 } }}
        >
          <Grid container rowGap={10}>
            <Grid
              item
              xs={12}
              sx={{ display: "flex", justifyContent: "center" }}
            >
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "28px",
                    md: "38px",
                    lg: "48px",
                  },
                  lineHeight: {
                    xs: "34px",
                    sm: "50px",
                    md: "60px",
                    lg: "73px",
                  },
                  fontWeight: 500,
                  color: "#201D28",
                  textAlign: "center",
                  wordBreak: "break-word",
                  whiteSpace: "normal",
                }}
                className="fade-in-up-whoweare"
              >
                {/* ADManager Plus Features */}
                {featuresTitle?.title}
              </Typography>
            </Grid>
            {itSolutionFeatures.length > 0 && (
              <Grid item xs={12}>
                <Box
                // sx={{ width: "100%" }}
                >
                  <TabContext value={value}>
                    <Box
                      sx={{
                        borderBottom:
                          itSolutionFeatures && itSolutionFeatures.length > 0
                            ? 1
                            : 0,
                        borderColor: "divider",
                      }}
                    >
                      <TabList
                        variant={
                          isMobile
                            ? "scrollable"
                            : itSolutionFeatures.length >= 7
                            ? "scrollable"
                            : "fullWidth"
                        }
                        onChange={handleChange}
                        aria-label="lab API tabs example"
                        // sx={{
                        //   "& .MuiTabs-flexContainer": {
                        //     display: "flex",
                        //     justifyContent: "space-between",
                        //   },
                        // }}
                      >
                        {itSolutionFeatures?.map((item, index) => (
                          <CustomTab
                            key={index}
                            // icon={
                            //   <Box
                            //     sx={{
                            //       height: { xs: "20px", sm: "29px" },
                            //       width: { xs: "20px", sm: "29px" },
                            //     }}
                            //   >
                            //     <img
                            //       src={
                            //         value === "management"
                            //           ? managementActiveIcon
                            //           : managementIcon
                            //       }
                            //       style={{ height: "100%", width: "100%" }}
                            //     />
                            //   </Box>
                            // }
                            // iconPosition="start"
                            label={item.title}
                            value={item.title}
                            wrapped
                          />
                        ))}
                      </TabList>
                    </Box>
                    {itSolutionFeatures.map((item, index) => (
                      <Fade
                        in={value === item.title}
                        timeout={1000}
                        key={index}
                      >
                        <CustomTabPanel value={item.title}>
                          <ADManagerCards
                            features={subFeaturesData[item.title] || []}
                            //  value="management"
                          />
                        </CustomTabPanel>
                      </Fade>
                    ))}
                  </TabContext>
                </Box>
              </Grid>
            )}
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default ADManager;
