import React, { useState } from "react";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import ADManager from "src/views/pages/ITSolutionDetails/ITSolutionFeatures/ADManager";
import ADManagerList from "src/views/pages/ITSolutionDetails/ITSolutionFeatures/ADManagerList";
import { toastError, toastSuccess } from "src/utils/utils";
import { Box } from "@mui/material";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";

const ITSolutionFeaturesPage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);
  const [featuresTitle, setFeaturesTitle] = useState({});
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  //animation
  // useEffect(() => {
  //   const handleScroll = () => {
  //     const offset = window.pageYOffset || document.documentElement.scrollTop;
  //     setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
  //   };

  //   window.addEventListener("scroll", handleScroll);
  //   handleScroll(); // Initialize position

  //   return () => {
  //     window.removeEventListener("scroll", handleScroll);
  //   };
  // }, []);
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset);
    };

    let animationFrameId;
    const onScroll = () => {
      animationFrameId = requestAnimationFrame(handleScroll);
    };

    window.addEventListener("scroll", onScroll);

    return () => {
      window.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  const fetchFeaturesTitle = () => {
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_FEATURES_TITLE.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        responseData.map((item) => {
          setFeaturesTitle(item);
        });
      })
      .catch((error) => {
        toastError(error);
      });
  };

  useEffect(() => {
    fetchFeaturesTitle();
  }, [id]);
  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <ADManager featuresTitle={featuresTitle} />
        <ADManagerList />
      </Box>
    </>
  );
};

export default ITSolutionFeaturesPage;
